import React, { useState } from "react";

// Spice-inspired palettes: saffron, chili red, turmeric, curry-leaf green.
const PALETTES = [
  ["#FFB300", "#CB202D", "#267E3E"],
  ["#CB202D", "#1C1C1C", "#FFB300"],
  ["#FFB300", "#267E3E", "#A81820"],
];

// Renders a real photo when `image` is set; falls back to generated dish art
// if there's no image yet, or the URL fails to load (e.g. a broken link).
export default function DishArt({ seed = 0, image = "" }) {
  const [broken, setBroken] = useState(false);

  if (image && !broken) {
    return (
      <img
        src={image}
        alt=""
        onError={() => setBroken(true)}
        style={{ width: "100%", height: 130, objectFit: "cover", display: "block", background: "var(--panel)" }}
      />
    );
  }

  const p = PALETTES[seed % PALETTES.length];
  return (
    <svg viewBox="0 0 200 120" style={{ width: "100%", height: 130, display: "block", background: "var(--panel)" }}>
      <ellipse cx="100" cy="90" rx="86" ry="18" fill={p[0]} opacity="0.25" />
      <ellipse cx="100" cy="70" rx="78" ry="30" fill="#FFFFFF" />
      {/* curry / gravy base */}
      <ellipse cx="100" cy="66" rx="72" ry="24" fill={p[0]} opacity="0.88" />
      {/* garnish: paneer / veg pieces */}
      <circle cx="70" cy="58" r="10" fill={p[1]} />
      <circle cx="110" cy="50" r="8" fill={p[2]} />
      <circle cx="130" cy="66" r="7" fill="#1C1C1C" />
      <circle cx="90" cy="70" r="7" fill="#FAFAFA" />
      {/* fresh coriander fleck */}
      <circle cx="105" cy="62" r="3" fill="#267E3E" />
      <circle cx="80" cy="72" r="2.5" fill="#267E3E" />
      {/* rising steam wisps */}
      <path d="M78 40 Q84 28 78 18" stroke="#FFFFFF" strokeWidth="3" fill="none" strokeLinecap="round" opacity="0.55" />
      <path d="M100 36 Q106 22 100 10" stroke="#FFFFFF" strokeWidth="3" fill="none" strokeLinecap="round" opacity="0.5" />
      <path d="M122 40 Q128 28 122 18" stroke="#FFFFFF" strokeWidth="3" fill="none" strokeLinecap="round" opacity="0.55" />
    </svg>
  );
}
